  ui_story_30460201_14_dialog_content = "...",
  ui_story_30460201_15_dialog_content = "Seu rosto não mudou, mas quem garante que ele não tá prestes a explodir?",
  ui_story_30460201_16_option_content = "Quem se atreveria?!",
  ui_story_30460201_17_dialog_content = "Digo, quem se atreveria a pregar uma peça no Senhor da Cidade?",
  ui_story_30460201_18_dialog_content = "Ninguém se atreveria, a não ser essas crianças.",
  ui_story_30460201_19_dialog_content = "Senhor da Cidade, está com raiva?",
  ui_story_30460201_20_dialog_content = "PlayerName fala tão alto quando bajula os outros. Obviamente, PlayerName está tentando cair nas graças de alguém♪",
  ui_story_30460201_21_dialog_content = "...",
  ui_story_30460201_22_dialog_content = "Você prega uma peça e depois tem a ousadia de perguntar se eu estou com raiva?",
  ui_story_30460201_23_dialog_content = "Raiva? Já que está aqui, por que não acalma essa raiva?",
  ui_story_30460201_24_dialog_content = "Jovem, você é o mestre da Colosso. Esse é o seu território, então você deve decidir.",
  ui_story_30460201_25_dialog_content = "Eu sei. Nesse caso, posso fazer um registro disso?",
  ui_story_30460201_26_dialog_content = "Eu só quero manter um registro de todos os principais incidentes que ocorreram na Colossus.",
  ui_story_30460201_27_dialog_content = "Um registro especial exclusivo da Colossus? Tudo bem, eu te dou minha permissão.",
  ui_story_30460201_28_dialog_content = "<size=70>Notícias da Colossus</size>",
  ui_story_30460201_29_dialog_content = "O <color=#FFB400>Incidente da flor de Keating</color> ocorreu na Colossus hoje. Vamos verificar mais a fundo.",
  ui_story_30460201_30_dialog_content = "Isso é baseado na cena e na narração de Schwartz, o Senhor da Cidade.",
  ui_story_30460201_31_dialog_content = "Dá pra perceber que ele suspeita claramente do quarteto Keating...",
  ui_story_30460201_32_dialog_content = "Você... Essa é uma maneira bem especial de registrar as coisas.",
  ui_story_30460201_33_dialog_content = "Cof, Vice e eu tivemos essa ideia...",
  ui_story_30460201_34_dialog_content = "Criamos esse novo método de registro após consultarmos muitas fontes de informação e estamos testando-o no momento.",
  ui_story_30460201_35_dialog_content = "Todos os registros de incidentes serão anexados com explicações detalhadas e dinâmicas, tornando-os precisos e fáceis de ler.",
  ui_story_30460201_36_dialog_content = "PlayerName♪ você não está deixando Keating falar♪",
  ui_story_30460201_37_dialog_content = "Está tentando nos excluir? Você só quer brincar com o Senhor da Cidade?",
  ui_story_30460201_38_dialog_content = "Desculpe, me deixe apenas fazer um registro descritivo primeiro.",
  ui_story_30460201_39_dialog_content = "Vamos começar oficialmente, então. Em breve peço pra você falar.",
  ui_story_30460201_40_dialog_content = "Para esse registro, você precisará <color=#FFB400>prestar atenção à formalidade de suas palavras e ao efeito da tela.</color>",
  ui_story_30460201_41_dialog_content = "Chega de explicação. Comece logo...",
  ui_story_30460201_42_dialog_content = "Na verdade, o grupo do qual o reclamante suspeita parece não estar satisfeito com sua conclusão.",
  ui_story_30460201_43_dialog_content = "Quem? O quê?",
  ui_story_30460201_44_dialog_content = "Foram vocês. Colocaram uma flor na minha orelha quando eu descansava.",
  ui_story_30460201_45_dialog_content = "Isso é um mal-entendido.",
  ui_story_30460201_46_dialog_content = "Está com raiva porque confundiu a flor com uma brincadeira.",
  ui_story_30460201_47_dialog_content = "Não deveria ficar com raiva.",
  ui_story_30460201_48_dialog_content = "Por quê?",
  ui_story_30460201_49_dialog_content = "Porque a oferenda de uma flor representa respeito.",
  ui_story_30460201_50_dialog_content = "Foi o que <color=#FFB400>Uriah</color> nos ensinou.",
  ui_story_30460201_51_dialog_content = "Desculpe, vou ter que interromper. Posso fazer algumas perguntas?",
  ui_story_30460201_52_dialog_content = "Vou escrever tudo nas notas do registro.",
  ui_story_30460201_53_dialog_content = "PlayerName, quer fazer uma pergunta? Pode perguntar♪",
  ui_story_30460201_54_option_content = "Perguntar sobre a flor.",
  ui_story_30460201_55_dialog_content = "Como você conseguiu encontrar essa flor branca na Colosso?",
  ui_story_30460201_56_dialog_content = "Você ainda não sabe, não sabe o que perguntar♪",
  ui_story_30460201_57_dialog_content = "Essa é uma flor branca especial que a <color=#FFB400>irmã mais velha</color> cultivou com sua Lúmina. Ela floresceu por causa da magia da <color=#FFB400>irmã mais velha</color>♪",
  ui_story_30460201_58_dialog_content = "Certo, vou anotar isso.",
  ui_story_30460201_59_option_content = "Perguntar sobre irmã mais velha.",
  ui_story_30460201_60_dialog_content = "Ela é a nossa amada <color=#FFB400>Uriah</color>, nossa querida veterana da Academia♪",
  ui_story_30460201_61_dialog_content = "Ela nos ensinou a falar e a cantar para os nobres♪",
  ui_story_30460201_62_dialog_content = "Essa é uma informação interessante.",
  ui_story_30460201_63_dialog_content = "Entendi. Anotado.",
  ui_story_30460201_64_dialog_content = "Além disso, tenho a sensação de que vocês não respeitam muito Senhor da Cidade.",
  ui_story_30460201_65_dialog_content = "Conflitos como esse podem adicionar drama aos registros.",
  ui_story_30460201_66_dialog_content = "Mas estava pra perguntar há bastante tempo. A maneira como fala com o Senhor da Cidade...",
  ui_story_30460201_67_option_content = "Você não acha que há problema?",
  ui_story_30460201_68_dialog_content = "Temos todo respeito♪ pelo querido Senhor da Cidade♪",
  ui_story_30460201_69_dialog_content = "É claro que o tratamos de maneira diferente da que tratamos você, PlayerName♪",
  ui_story_30460201_70_dialog_content = "Haha, comparando com a forma como tratam os outros nobres, eles são até muito educados com você.",
  ui_story_30460201_71_dialog_content = "Espere aí, eu não estava falando pelo Senhor da Cidade agora mesmo?",
  ui_story_30460201_72_dialog_content = "Por que tenho impressão de estar sendo atacado?",
  ui_story_30460201_73_dialog_content = "Obviamente o Senhor da Cidade gosta de nós e conhece bem a nossa personalidade.",
  ui_story_30460201_74_dialog_content = "Entendi, então isso que é ser apoiado por alguém no poder...",
  ui_story_30460201_75_option_content = "Senhor, você se importa?",
  ui_story_30460201_76_dialog_content = "São apenas palavras rebeldes de algumas crianças. É claro que não vou levá-las a sério.",
  ui_story_30460201_77_dialog_content = "O Senhor da Cidade nos escolheu pessoalmente.",
  ui_story_30460201_78_dialog_content = "O Senhor da Cidade sabia o tipo de criança que nós éramos e nos deixou entrar para o Coro.",
  ui_story_30460201_79_dialog_content = "Isso é verdade?",
  ui_story_30460201_80_dialog_content = "Fui eu que tomei essa decisão, é óbvio que a natureza deles serve algum propósito pra mim.",
  ui_story_30460201_81_dialog_content = "Não admira que sejam incorrigíveis! Deve ser isso que significa ser apoiado por gente importante...",
  ui_story_30460201_82_dialog_content = "Certo, já que o Senhor da Cidade não se importa, continuarei registrando conflitos dramáticos como esse.",
  ui_story_30460201_83_dialog_content = "Vamos continuar gravando. 3, 2, 1... Ação!",
  ui_story_30460201_84_dialog_content = "É assim que você oferece flores? Enfiando atrás das orelhas das pessoas?",
  ui_story_30460201_85_dialog_content = "Porque fica bonito assim.",
  ui_story_30460201_86_dialog_content = "Porque fica elegante assim.",
  ui_story_30460201_87_dialog_content = "Um monte de bobagem.",
  ui_story_30460201_88_dialog_content = "Bom, porque é verdade.",
  ui_story_30460201_89_dialog_content = "Verdade? Então é bom que tenha provas suficientes para confirmar isso.",
  ui_story_30460201_90_dialog_content = "A verdade é que nossa querida irmã Uriah também fez algo semelhante conosco.",
  ui_story_30460201_91_dialog_content = "Ela nos abençoava com um sorriso e colocava uma linda flor atrás da nossa orelha.",
  ui_story_30460201_92_dialog_content = "Foi isso que aprendemos. É isso que sabemos.",
  ui_story_30460201_93_dialog_content = "Humpf, então agora você pretende jogar a responsabilidade para outra pessoa?",
  ui_story_30460201_94_dialog_content = "Desculpe, deixe-me interrompê-los de novo. Isso não coincide com o que vocês disseram antes?",
  ui_story_30460201_95_dialog_content = "PlayerName, você está sempre interrompendo as pessoas.",
  ui_story_30460201_96_dialog_content = "O Senhor da Cidade está extremamente ocupado.",
  ui_story_30460201_97_dialog_content = "Era pra ser apenas algumas perguntas.",
  ui_story_30460201_98_dialog_content = "Mas agora isso se estendeu indefinidamente.",
  ui_story_30460201_99_dialog_content = "Se tornou um problema maior.♪",
  ui_story_30460201_100_dialog_content = "Eu não me importo, mas de fato você deve se atentar. Meu tempo é limitado, então vamos acabar logo com isso.",
  ui_story_30460201_101_dialog_content = "Perdoe-me, vou editar após gravar o que falarmos a seguir. Por favor, diga algo para concluir.",
  ui_story_30460201_102_dialog_content = "3, 2, 1... Ação!",
  ui_story_30460201_103_dialog_content = "Não estamos fugindo de nossas responsabilidades,apenas falando a verdade.",
  ui_story_30460201_104_dialog_content = "Além disso, somos apenas crianças. Por que você está criando caso?",
  ui_story_30460201_105_dialog_content = "Vocês são crianças, mas devem aprender uma lição quando for necessário.",
  ui_story_30460201_106_dialog_content = "Crianças não devem ser mimadas.",
  ui_story_30460201_107_dialog_content = "A partir de agora, a situação fica resolvida.",
  ui_story_30460201_108_dialog_content = "Embora as crianças Keating tenham alegado que nunca pregaram peças...",
  ui_story_30460201_109_dialog_content = "O Senhor Schwartz pretende responsabilizá-las depois disso.",
  ui_story_30460201_110_dialog_content = "Esse é o relatório de registro preparado por PlayerName, relator da Colossus.",
  ui_story_30460201_111_dialog_content = "Navegador: PlayerName\nRepórter no local: PlayerName\nPessoas presentes: Niel, do Keating Coro\n Cara, do Keating Coro\n Pierre, do Keating Coro\n Diana, do Keating Coro\n Senhor Schwartz, Senhor da Cidade de Lumopolis",
  ui_story_30460201_112_dialog_content = "Que interessante. Nada mau esse relatório.",
  ui_story_30460201_113_dialog_content = "Agradeço o apoio, Senhor da Cidade. Seu discurso foi simplesmente perfeito.",
  ui_story_30460201_114_dialog_content = "Embora o incidente seja registrado de forma diferente do que os de Lumópolis, não se preocupe porque posso entendê-lo.",
  ui_story_30460201_115_dialog_content = "Encerramos este assunto. Tenho outras coisas para tratar agora.",
  ui_story_30460201_116_dialog_content = "Cuide-se bem, Senhor da Cidade.",
  ui_story_30460201_117_dialog_content = "PlayerName, você está nos ignorando e falando apenas com o Senhor da Cidade novamente.",
  ui_story_30460201_118_dialog_content = "PlayerName tenta ter respeito,",
  ui_story_30460201_119_dialog_content = "mas se expressa de forma estranha.",
  ui_story_30460201_120_dialog_content = "Foi um fracasso.",
  ui_story_30460201_121_dialog_content = "Vocês deveriam ser um pouco mais compreensivos, já que nem Senhor da Cidade falou alguma coisa.",
  ui_story_30460201_122_dialog_content = "Não estudei nada sobre etiqueta de corte, então já estou tentando o meu melhor para mostrar respeito.",
  ui_story_30460201_123_dialog_content = "Crianças, também está na gravação o Senhor da Cidade dizendo para não mimar vocês.",
  ui_story_30460201_124_dialog_content = "Mas sinto que ele ainda é bastante tolerante com vocês.",
  ui_story_30460201_125_dialog_content = "É verdade.",
  ui_story_30460601_1_dialog_content = "\"No momento em que você abrir este Tomo de Magia Negra,\"",
  ui_story_30460601_2_dialog_content = "\"Você será transportado para um novo mundo misterioso.\"",
  ui_story_30460601_3_dialog_content = "\"Um mundo de maravilhas e magia,\"",
  ui_story_30460601_4_dialog_content = "\"Cheio de todos os tipos de coisas extraordinárias.\"",
  ui_story_30460601_5_dialog_content = "\"Um mundo para almas curiosas e solitárias.\"",
  ui_story_30460601_6_dialog_content = "O que você acha? A introdução desse livro sabe mesmo como prender a atenção do leitor, né?",
  ui_story_30460601_7_dialog_content = "Este \"Tomo de Magia Negra\" também é a razão de vocês estarem vestidos assim?",
  ui_story_30460601_8_dialog_content = "Posso garantir a você, meu amigo adulto e ignorante, que este livro contém magia negra real e proibida.",
  ui_story_30460601_9_dialog_content = "E você diz que uma senhora estranha na rua deu isso para você?",
  ui_story_30460601_10_dialog_content = "Tem certeza que ela não estava mentindo?",
  ui_story_30460601_11_dialog_content = "Ao contrário de você, não somos tão facilmente enganados.",
  ui_story_30460601_12_dialog_content = "Ela continuou falando sobre como o livro é aterrorizante!",
  ui_story_30460601_13_dialog_content = "Tenho certeza que ela só estava fazendo isso para chamar sua atenção.",
  ui_story_30460601_14_dialog_content = "Ela também disse que este livro é aterrorizante apenas para adultos. Para crianças pequenas como nós, é perfeitamente seguro!",
  ui_story_30460601_15_dialog_content = "Você está brincando certo? Ela obviamente estava enganando você para que comprasse este livro!",
  ui_story_30460601_16_dialog_content = "Quanto você pagou a ela? Vamos lá, eu te ajudo a ter seu dinheiro de volta!",
  ui_story_30460601_17_dialog_content = "Ela não queria nosso dinheiro.",
  ui_story_30460601_18_dialog_content = "Huh? Então foi grátis...",
  ui_story_30460601_19_dialog_content = "Você acha que ainda há um problema agora?",
  ui_story_30460601_20_option_content = "Se fosse de graça, acho que não.",
  ui_story_30460601_21_dialog_content = "♫Frugalidade é uma mentira que os adultos escondem, a terrível ganância que guardam dentro de si!♪",
  ui_story_30460601_22_dialog_content = "Só estou guardando por curiosidade!",
  ui_story_30460601_23_option_content = "Além disso, nada na vida é de graça, você sabe!",
  ui_story_30460601_24_dialog_content = "♫E assim, no final das contas, o dinheiro ainda governa todos os jogos que eles jogam!♪",
  ui_story_30460601_25_dialog_content = "Sim, sim, sinta-se livre para pensar o que quiser.",
  ui_story_30460601_26_dialog_content = "Então, que tipo de livro é esse, afinal?",
  ui_story_30460601_27_dialog_content = "Acho que não faria mal deixar você dar uma olhada.",
  ui_story_30460601_28_dialog_content = "Se alguma coisa, você pode ser capaz de ajudar.",
  ui_story_30460601_29_dialog_content = "É um antigo livro de magia proibida. A maior parte já foi perdida.",
  ui_story_30460601_30_dialog_content = "Mas na última página...",
  ui_story_30460601_31_dialog_content = "\"Nome: Monstro Titanic...\"",
  ui_story_30460601_32_dialog_content = "(Huh, o resto está além do reconhecimento.)",
  ui_story_30460601_33_dialog_content = "Materiais: melão amargo, aipo, pimenta verde...",
  ui_story_30460601_34_dialog_content = "Espere, estes são apenas ingredientes culinários comuns!",
  ui_story_30460601_35_dialog_content = "Você pode querer dar uma olhada na próxima linha.",
  ui_story_30460601_36_dialog_content = "Tentáculos coleóides, muco Koppia Caterpillar, barbatanas de cavala.",
  ui_story_30460601_37_dialog_content = "Uhh... O que diabos são essas coisas?",
  ui_story_30460601_38_dialog_content = "Alguns ingredientes pegajosos e carnudos de origens desconhecidas, aparentemente.",
  ui_story_30460601_39_dialog_content = "Agora você acredita que este livro está cheio de magia negra?",
  ui_story_30460601_40_dialog_content = "(Tenho certeza de que é apenas uma receita estranha, mas provavelmente é assustadora para crianças pequenas como eles. Talvez eu deva apenas brincar por enquanto ...)",
  ui_story_30460601_41_dialog_content = "É verdade, há algo de assustador nos materiais listados aqui...",
  ui_story_30460601_42_dialog_content = "Apenas lê-los em voz alta dá arrepios.",
  ui_story_30460601_43_dialog_content = "Eis que este é o lendário Celestita. Como você é \"lendário\"!",
  ui_story_30460601_44_dialog_content = "Eu não brincaria muito, pessoal. E se esse feitiço puder realmente invocar um monstro grande e horrível?",
  ui_story_30460601_45_dialog_content = "Isso seria fantástico!",
  ui_story_30460601_46_dialog_content = "Vamos nos separar e procurar esses ingredientes!",
  ui_story_30460601_47_dialog_content = "Movam-se, todos!",
  ui_story_30460601_48_dialog_content = "Espere, vocês estão falando sério sobre isso?",
  ui_story_30460601_49_dialog_content = "Mas e se...",
  ui_story_30460601_50_dialog_content = "Os covardes estão condenados a se esconder nos bastidores.",
  ui_story_30460601_51_dialog_content = "Somente os corajosos são abençoados com milagres!",
  ui_story_30460601_52_dialog_content = "(Isso é fácil para você dizer, mas não poderei ficar parado se algo realmente acontecer.)",
  ui_story_30460601_53_dialog_content = "Se você quiser provar a si mesmo, deve nos fornecer um local para misturar esses ingredientes.",
  ui_story_30460601_54_dialog_content = "Huh? Por que eu?",
  ui_story_30460601_55_dialog_content = "(Heh, eu sabia que eles precisavam de mim! Vá em frente, me conte o quanto eu sou importante!)",
  ui_story_30460601_56_dialog_content = "Porque se você não ajudar, não teremos escolha a não ser usar a poção em você.",
  ui_story_30460601_57_dialog_content = "Quem sabe você pode até acordar com um monstro gigante no seu quarto!",
  ui_story_30460601_58_dialog_content = "Então agora você está me ameaçando?!",
  ui_story_30460601_59_dialog_content = "Eu acredito que os adultos chamam isso de \"quid pro quo\"?",
  ui_story_30460601_60_dialog_content = "Não jogue palavras quando você realmente não sabe o que elas significam!",
  ui_story_30460601_61_dialog_content = "(Eu estava planejando ajudá-los desde o início, mas agora parece que estou sendo forçado a fazê-lo...)",
  ui_story_30460601_62_dialog_content = "Tem uma panela grande na cozinha. Você pode usar isso como seu \"caldeirão\".",
  ui_story_30460601_63_dialog_content = "Você superestima severamente a força de seus utensílios de cozinha.",
  ui_story_30460601_64_dialog_content = "Além disso, não queremos danificar o Colossus de forma alguma.",
  ui_story_30460601_65_dialog_content = "Vocês têm certeza absoluta de que querem criar um monstro gigante?",
  ui_story_30460601_66_dialog_content = "Claro que estamos! Como poderia uma águia estar voando alto sem que sua ambição rugisse?",
  ui_story_30460601_67_dialog_content = "Tudo bem, então eu vou perguntar Carleen se houver algum laboratório abandonado em Lumopolis para você usar.",
  ui_story_30460601_68_dialog_content = "Embora não tenhamos muita confiança em sua capacidade de fazer as coisas...",
  ui_story_30460601_69_dialog_content = "com senhora Carleen do nosso lado, não devemos ter nada com que nos preocupar!",
  ui_story_30460601_70_dialog_content = "Agora vamos trabalhar!",
  ui_story_30460601_71_dialog_content = "Vejo vocês em breve!",
  ui_story_30460601_72_dialog_content = "Eu ouvi bem, querida? Você quer melão amargo, aipo e pimentão verde?",
  ui_story_30460601_73_dialog_content = "Achei que você sempre odiou essas coisas.",
  ui_story_30460601_74_dialog_content = "Tem toda a razão, minha querida mãe.",
  ui_story_30460601_75_dialog_content = "E ainda assim você está pedindo aqueles vegetais saudáveis! A mamãe não poderia estar mais orgulhosa de você, Niel!",
  ui_story_30460601_76_dialog_content = "Vou deixar o pessoal da cozinha fazer uma mala grande para você agora, ok?",
  ui_story_30460601_77_dialog_content = "Obrigada mãe. Por favor, não adicione mais nada também.",
  ui_story_30460601_78_dialog_content = "Meu pequeno Niel finalmente está aprendendo a comer seus vegetais! Eu estou tão feliz!",
  ui_story_30460601_79_dialog_content = "Isso é suficiente?",
  ui_story_30460601_80_dialog_content = "Sim mamãe. Agora, devo ir antes que suas lágrimas comecem a inundar a casa.",
  ui_story_30460601_81_dialog_content = "Antes de ir, deixe-me pedir ao chef que cozinhe algo para você. Como melão amargo recheado com aipo mais um prato de pimentão verde frito com salsa soa para você?",
  ui_story_30460601_82_dialog_content = "Eu quero ver você comer tudo!",
  ui_story_30460601_83_dialog_content = "Agradeço a preocupação, mas não estou com muita fome agora, mamãe.",
  ui_story_30460601_84_dialog_content = "Mas vai ajudá-lo a crescer grande e forte! Tente uma mordida!",
  ui_story_30460601_85_dialog_content = "Vou deixar você aproveitar esta refeição deliciosa e nutritiva, mamãe! Eu realmente, realmente tenho que ir agora! Tchau!",
  ui_story_30460601_86_dialog_content = "Puxa, ele fugiu tão rápido! Afinal, meu pequeno Niel deve estar comendo seus vegetais!",
  ui_story_30460601_87_dialog_content = "Ok, isso resolve! A partir de agora todas as refeições desta casa têm de incluir estes legumes!",
  ui_story_30460601_88_dialog_content = "Eu procurei em todos os livros, mas ainda nada!",
  ui_story_30460601_89_dialog_content = "Cara? Você está procurando algo em particular?",
  ui_story_30460601_90_dialog_content = "Sim, professor. Estou procurando um livro sobre biologia marinha.",
  ui_story_30460601_91_dialog_content = "Esse é o mesmo assunto que eu ensino! Hahahaha! Quando você se interessou tanto por esse campo, Kara?",
  ui_story_30460601_92_dialog_content = "Bem, estou tentando aprender mais sobre uma criatura chamada \"Coleoid\". Você deve saber tudo sobre isso, já que passou a vida inteira pesquisando animais marinhos, certo?",
  ui_story_30460601_93_dialog_content = "Na verdade, ninguém na Academia tem mais conhecimento sobre esse assunto do que eu. Na verdade, eu até mantenho alguns tentáculos de Coleoid em meu escritório!",
  ui_story_30460601_94_dialog_content = "Os mais velhos adoram inventar histórias que nunca existiram quando eram mais novos, não é?",
  ui_story_30460601_95_dialog_content = "Não estou inventando nada, Kara! Os tentáculos estão no meu armário! Se bem me lembro, foi há trinta anos que...",
  ui_story_30460601_96_dialog_content = "Se você vai se perder em suas memórias, professor. Você poderia pelo menos pular para a parte importante?",
  ui_story_30460601_97_dialog_content = "Er, v-muito bem, então. Na minha juventude, encontrei uma linda mulher enquanto pesquisava diferentes espécimes perto do oceano...",
  ui_story_30460601_98_dialog_content = "Deixe-me adivinhar: você se apaixonou, mas ela não sentiu o mesmo?",
  ui_story_30460601_99_dialog_content = "S-Sim, isso mesmo. De qualquer forma, descobri uma caverna cárstica à beira-mar logo depois, e nessa caverna...",
  ui_story_30460601_100_dialog_content = "Quanto mais uma história se arrasta, pior será o final.",
  ui_story_30460601_101_dialog_content = "Eu me deparei com isso! Ver? Tentáculos coleóides, como eu disse!",
  ui_story_30460601_102_dialog_content = "E assim, o bravo herói finalmente reivindica o tesouro.",
  ui_story_30460601_103_dialog_content = "Eu não poderia concordar mais! Afinal, eu era um rapaz muito corajoso na minha época...",
  ui_story_30460601_104_dialog_content = "Não, não você professor. Eu sou o herói, e esta é minha recompensa por assistir a sua longa história.",
  ui_story_30460601_105_dialog_content = "Eh? M-Mas eu arrisquei minha vida por esses tentáculos trinta anos atrás!",
  ui_story_30460601_106_dialog_content = "O que significa que você teve trinta anos para comemorar sua conquista, então o que mais você poderia querer? A menos, é claro, que você tenha inventado tudo...",
  ui_story_30460601_107_dialog_content = "Posso garantir que minha história é totalmente verdadeira. Vá em frente e pegue-os, mas lembre-se de...",
  ui_story_30460601_108_dialog_content = "Espere, onde você está indo? Eu não tinha terminado de falar ainda! Deus, o que diabos essa garotinha está aprontando?",
  ui_story_30460601_109_dialog_content = "Com licença...",
  ui_story_30460601_110_dialog_content = "Bem, se não é uma garotinha nobre de Uptown!",
  ui_story_30460601_111_dialog_content = "Parece que há algo errado com seus olhos.",
  ui_story_30460601_112_dialog_content = "Só não estamos acostumados a ver pessoas nobres em nossos mercados, só isso.",
  ui_story_30460601_113_dialog_content = "Oh, senhorita, você é muito bonita. Olhe para o seu cabelo brilhante!",
  ui_story_30460601_114_dialog_content = "Então, o que a traz a Lower Lumopolis, senhorita? Você não está perdido, está?",
  ui_story_30460601_115_dialog_content = "Se você apenas me deixasse falar, não teria que fazer essas perguntas desnecessárias.",
  ui_story_30460601_116_dialog_content = "Preciso de barbatanas de cavala e preciso delas agora. Por favor.",
  ui_story_30460601_117_dialog_content = "Até a voz dela é bonita, não acham?",
  ui_story_30460601_118_dialog_content = "Eu me lembro agora! ela faz parte do Keating Coro!",
  ui_story_30460601_119_dialog_content = "Não é à toa que ela tem uma voz tão melódica!",
  ui_story_30460601_120_dialog_content = "Realmente? Mas eu não ouvi o que ela disse agora há pouco! Você poderia, por favor, dizer isso de novo, senhorita?",
  ui_story_30460601_121_dialog_content = "Provocar o Coro é incorrer na ira do Deus da Luz.",
  ui_story_30460601_122_dialog_content = "Oh, sinto muito! Eu não quis te ofender!",
  ui_story_30460601_123_dialog_content = "Uma idade tão jovem para um membro do Coro. Isso é realmente algo para você!",
  ui_story_30460601_124_dialog_content = "Dediquem-se à Luz, não às suas triviais atividades mortais.",
  ui_story_30460601_125_dialog_content = "Claro, claro. De qualquer forma, essas barbatanas de cavala são bastante raras, mas não tão raras quanto ter um nobre como cliente. Terei o maior prazer em vendê-los para você!",
  ui_story_30460601_126_dialog_content = "A Lagarta Koppia... Enorme em tamanho, mas de temperamento gentil, vive nas profundezas das florestas, gostando particularmente de dormir.",
  ui_story_30460601_127_dialog_content = "Como filho de um Cavaleiro, explorar a floresta é apenas mais uma prova necessária em minha jornada!",
  ui_story_30460601_128_dialog_content = "Posso estar sozinho, mas enquanto tiver minha espada, não tenho nada a temer!",
  ui_story_30460601_129_dialog_content = "O chão é macio, e há um cheiro incomum no ar... Ah!",
  ui_story_30460601_130_dialog_content = "Gorgolejar, gorgolejar, gorgolejar——",
  ui_story_30460601_131_dialog_content = "(Onde... Onde estou? Esta respiração quente e rítmica e esta sensação de toque pegajoso...)",
  ui_story_30460601_132_dialog_content = "(Devo estar dentro da boca de um monstro gigante... Mais uma prova a superar!)",
  ui_story_30460601_133_dialog_content = "Ufa... Finalmente livre.",
  ui_story_30460601_134_dialog_content = "Que nojento... Basta olhar para todo esse muco. Graças a Deus ninguém está por perto para me ver assim.",
  ui_story_30460601_135_dialog_content = "Tudo bem aí, pequenino? O que você está fazendo na floresta sozinho?",
  ui_story_30460601_136_dialog_content = "Estou bem. Minha espada pode perfurar a garganta de qualquer monstro!",
  ui_story_30460601_137_dialog_content = "Bem, tanto quanto posso dizer, você teve um desentendimento com um Koppia Caterpillar, não foi?",
  ui_story_30460601_138_dialog_content = "Eles gostam de se enterrar no chão e dormir com a boca bem aberta. Por acaso você caiu na boca dele?",
  ui_story_30460601_139_dialog_content = "S-Sim, mas apenas porque o objetivo do meu teste era obter um pouco de seu muco! Isso é tudo!",
  ui_story_30460601_140_dialog_content = "Ei, preste atenção onde pisa! Você não quer cair na boca de outro, né?!",
  ui_story_30460601_141_dialog_content = "Este deve ser o laboratório mágico abandonado que Carleen me contou sobre.",
  ui_story_30460601_142_dialog_content = "É enorme e longe do caminho. Carleen até designou uma equipe de soldados para guardar o perímetro.",
  ui_story_30460601_143_dialog_content = "Mesmo que algo realmente acontecesse, tenho certeza de que eles poderiam lidar com as coisas rapidamente.",
  ui_story_30460601_144_dialog_content = "Eu acho Carleen deve realmente se preocupar em deixar essas crianças explorar e aprender.",
  ui_story_30460601_145_dialog_content = "Eu me pergunto o que diabos eles vão inventar?",
  ui_story_30460601_146_dialog_content = "♪Os ingredientes foram reunidos, a hora é agora.♪",
  ui_story_30460601_147_dialog_content = "♪ Enquanto o caldeirão borbulha, leia o encantamento em voz alta! ♪",
  ui_story_30460601_148_dialog_content = "♪ Chamas bruxuleantes e mistura rodopiante, ♪",
  ui_story_30460601_149_dialog_content = "♪A verdadeira magia dispensa apresentações!♪",
  ui_story_30460601_150_dialog_content = "♫May nossos jovens corações dão nova vida a este feitiço!♫",
  ui_story_30460601_151_dialog_content = "(Seus olhos estão brilhando tanto. Deve ser assim que as crianças ficam quando estão se divertindo aprendendo.)",
  ui_story_30460601_152_dialog_content = "COF cof! Tanta fumaça!",
  ui_story_30460601_153_dialog_content = "Nada de bom! Eu não consigo ver nada!",
  ui_story_30460601_154_dialog_content = "Uma sombra! Emergindo da fumaça!",
  ui_story_30460601_155_dialog_content = "Eu acho que está se movendo!",
  ui_story_30460601_156_dialog_content = "Oh não, estou sentindo uma onda de energia muito forte! Fiquem atrás de mim, pessoal!",
  ui_story_30460601_157_dialog_content = "E o que exatamente VOCÊ vai fazer?",
  ui_story_30460601_158_dialog_content = "Não deveria ser você quem está se escondendo atrás de nós?",
  ui_story_30460601_159_dialog_content = "Já dissemos antes, vamos protegê-lo quando surgir a necessidade.",
  ui_story_30460601_160_dialog_content = "Por favor, não se preocupe conosco.",
  ui_story_30460601_161_dialog_content = "<color=#e8d9bb>Baque——</color>",
  ui_story_30460601_162_dialog_content = "Que barulho ensurdecedor! É um demônio mítico ou algo assim? Não, é um Eclipsite!",
  ui_story_30460601_163_dialog_content = "Por favor, deixe-nos ir.",
  ui_story_30460601_164_dialog_content = "Por favor, abra seus olhos.",
  ui_story_30460601_165_dialog_content = "Isso não é nenhum monstro——",
  ui_story_30460601_166_dialog_content = "É apenas o nosso professor.",
  ui_story_30460601_167_dialog_content = "O que diabos está acontecendo aqui?",
  ui_story_30460601_168_dialog_content = "Um livro de feitiços proibido de magia negra?! Achei que Kara estava estranha hoje, então decidi segui-la, mas nunca esperei...",
  ui_story_30460601_169_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_30460601_170_dialog_content = "Está pronto!",
  ui_story_30460601_171_dialog_content = "Nasce um milagre!",
  ui_story_30460601_172_dialog_content = "Parece um pouco estranho...",
  ui_story_30460601_173_dialog_content = "Mas também um pouco fofo!",
  ui_story_30460601_174_dialog_content = "Isso é... Um bolo gigante?",
  ui_story_30460601_175_dialog_content = "Fique atrás! Este bolo ainda é obra de magia negra! Provavelmente é venenoso!",
  ui_story_30460601_176_dialog_content = "Mmm, não admira que este bolo seja proibido. É delicioso!",
  ui_story_30460601_177_dialog_content = "V-Você já deu uma mordida?! Fale agora mesmo, Kara!",
  ui_story_30460601_178_dialog_content = "Dizem que o sabor está próximo da piedade, sabe?",
  ui_story_30460601_179_dialog_content = "Você também não, Pierre?!",
  ui_story_30460601_180_dialog_content = "Nossa, realmente é delicioso! Experimente, professor!",
  ui_story_30460601_181_dialog_content = "Eu posso ver as crianças fazendo isso, Sr. Celestita, mas você? Por favor, você deve parar com essa tolice...",
  ui_story_30460601_182_dialog_content = "Eu não sabia que melão amargo e pimentão verde poderiam ser usados para fazer algo tão delicioso!",
  ui_story_30460601_183_dialog_content = "Melão amargo e pimentão, você diz? Bem, parece saudável o suficiente... Ah, que diabos, vou tentar.",
  ui_story_30460601_184_dialog_content = "Minha palavra! É realmente delicioso!",
  ui_story_30460601_185_dialog_content = "E com isso, nosso experimento finalmente acabou.",
  ui_story_30460601_186_dialog_content = "Acho que não, Diana! Este assunto ainda precisa ser relatado à Academia.",
  ui_story_30460601_187_dialog_content = "Um bolo tão saudável e delicioso deve ser compartilhado com toda a escola!",
  ui_story_30460601_188_dialog_content = "*Munch* Este bolo é ótimo e tudo...",
  ui_story_30460601_189_dialog_content = "*Munch* Mas ainda há um pequeno problema.",
  ui_story_30460601_190_dialog_content = "*Munch* Fomos enganados, não fomos?",
  ui_story_30460601_191_dialog_content = "*Munch* Este é claramente um livro de receitas, não um tomo de magia negra.",
  ui_story_30460601_192_dialog_content = "*Munch* Você só está percebendo isso agora...?",
  ui_story_30460601_193_dialog_content = "O que... Por que vocês estão todos deitados no chão assim? Você está machucado?",
  ui_story_30460601_194_dialog_content = "Ei Chloe... Não, não, não chore! Estamos perfeitamente bem!",
  ui_story_30460601_195_dialog_content = "Comemos tanto bolo que não conseguimos nos mexer.",
  ui_story_30460601_196_dialog_content = "E agora Chloe o Crybaby se assustou.",
  ui_story_30460601_197_dialog_content = "Aqui, guardamos um último pedaço do bolo.",
  ui_story_30460601_198_dialog_content = "Coma. Espero que remedie sua mágoa.",
  ui_story_30460601_199_dialog_content = "Você mesmo fez este bolo?",
  ui_story_30460601_200_dialog_content = "Huh? Como você sabia?",
  ui_story_30460601_201_dialog_content = "Bem, parece um pouco estranho demais para ser comprado em loja...",
  ui_story_30460601_202_dialog_content = "Acho que você está certo. Não faço ideia de quem compraria um bolo desses...",
  ui_story_30460601_203_dialog_content = "Parece que o bebê chorão ficou mais perspicaz.",
  ui_story_30460601_204_dialog_content = "Mas ainda assim, seu julgamento dificilmente é objetivo.",
  ui_story_30460601_205_dialog_content = "Sim, nosso bolo tem um exterior feio,",
  ui_story_30460601_206_dialog_content = "Mas logo você descobrirá que seu sabor é muito superior!",
  ui_story_30460601_207_dialog_content = "Desculpe, sei que não devo julgar seu bolo pela aparência. Vou tentar agora mesmo.",
  ui_story_30460601_208_dialog_content = "Como é?",
  ui_story_30460601_209_dialog_content = "Tem um gosto ótimo, mas é muito rico em calorias. É fácil ganhar peso se comer demais.",
  ui_story_30460601_210_dialog_content = "Calorias? Ganhando peso?",
  ui_story_30460601_211_dialog_content = "Espere, o que a senhora que nos deu este livro disse de novo?",
  ui_story_30460601_212_dialog_content = "\"Este livro é aterrorizante apenas para adultos. Para crianças pequenas como nós, é perfeitamente seguro!\"",
  ui_story_30460601_213_dialog_content = "Então a parte \"aterrorizante\"... O número de calorias do bolo era?!",
  ui_story_30460601_214_dialog_content = "...Fomos enganados..."
}
return config
